-- Flight Buddy :: PuttHard.lua
-- Each course's signature hazard, layered on its painted holes: Stormwind mages throw fireballs,
-- ghouls lob slime, orc war drums send shockwaves, wisps circle, tide pools flood, Ironforge gates
-- slam, gnome blowers push and Mulgore dust devils spin. One per hole at most; some holes stay clean.
-- Generated by place.py (positions in hole units, 480 x 560), then played by test bots for par.
local ADDON, NS = ...
local C = NS.PuttCourses
if not C then return end
local function X(course, key, extra)
    local c = C[course]
    if not c then return end
    for _, h in ipairs(c.holes) do if h.key == key then h.extra = extra end end
end
