-- Painted (mg_) holes: signature hazards layered on top of what the art generator already wired in.
local function Add(course, key, more)
    local c = C[course]
    if not c then return end
    for _, h in ipairs(c.holes) do
        if h.key == key then
            h.extra = h.extra or {}
            for k, v in pairs(more) do
                if k == "tip" or k == "par" then h[k] = v else
                    h.extra[k] = h.extra[k] or {}
                    for _, item in ipairs(v) do table.insert(h.extra[k], item) end
                end
            end
        end
    end
end
